// th16_s7_b14 — TH16 v1.00a Extra 关底 BossCard7「秘儀「七星の剣」」
// 源: st07bs.ecl.txt:1762-1814（entry）；依赖 BossCard7_at / BossCard7_at2 /
// BossCard7_at_et 见 1816-1865。卡帧 = 120 外壳缓冲 + 源帧。
// 源 Boss 在 BossCard7 入口位于 (0,128)（Boss:10-111 的 movePos），
// 在 t=0..60 内缓动到 (0,224)，t=90 生成 7 个子发射体。

const TH16_STAR_R: int = 608;   // 源 etSprite(1, 16, 6)：type 16 / color 6

const TIME_LIMIT: int = 4924;   // 120 缓冲 + 4800 源时限 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 BossCard7_at2：每 100 帧一次 32 路无瞄准整周环，基准角每波抽样一次 %RANDRAD。
async sub star_ring() {
    sh_reset(0);
    sh_sprite(0, TH16_STAR_R, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 32, 1);
    sh_speed(0, 1fx, 0fx);
    sh_dist(0, -4fx);   // 源 etEx(1,0,2,1,...)：ANIM a=1 出生 position -= 4*velocity
    loop {
        sh_angle(0, (rand(65536)) as angle, 0deg);
        sh_fire(0);
        wait(100);
    }
}

// 源 BossCard7_at_et：每 300 帧从自身位置生成一条 Infinite 激光。
// 角度取 Boss 的 %GF0（Boss→自机方向），7 个子敌共享同一方向。
// 源 laserNew(0, 32, 512, 0, 16) / laserTiming(0, 60, 30, 90, 30, 0)：
// 判定段 0.9*512，宽 16→目标 8（Infinite w<32 分支 h=w/4）；
// 三段 warn=startup=60，active=expand+1+hold=31+90=121，fade=shrink=30。
async sub laser_emitter() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);   // 源 flagSet(288) 的 0x20：停受击/体碰
    spawn star_ring();
    loop {
        _ = laser(6, $self_x, $self_y,
                  atan2($player_y - 224fx, $player_x - 0fx),
                  460.8fx, 8fx, 60, 121, 30);
        wait(300);
    }
}

// 源 BossCard7 入口主体：t=0 起 60 帧移到 (0,224)；t=90 生成 7 个子发射体；
// 此后源脚本每帧只刷新 %GF0（本卡在发射时刻现算）并空转。
// moveLimit(0,224,240,64) 在 Boss 静止于中心后不再可能触边，省略。
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);    // 源 setHitbox(48,48)
    set_hurtbox(20fx);   // 源 setHurtbox(40,40)
    move_to(60, 0fx, 224fx, EASE_QUAD_OUT);   // movePosTime(60, 4, 0, 224)
    wait(90);
    // 源 BossCard7_at()：enmCreateA 绝对坐标，hp=10 score=10 item=-1
    _ = spawn_enemy(160fx, 70fx, 10, 0, 10, 0, laser_emitter);
    _ = spawn_enemy(130fx, 120fx, 10, 0, 10, 0, laser_emitter);
    _ = spawn_enemy(60fx, 120fx, 10, 0, 10, 0, laser_emitter);
    _ = spawn_enemy(30fx, 70fx, 10, 0, 10, 0, laser_emitter);
    _ = spawn_enemy(-30fx, 50fx, 10, 0, 10, 0, laser_emitter);
    _ = spawn_enemy(-100fx, 50fx, 10, 0, 10, 0, laser_emitter);
    _ = spawn_enemy(-160fx, 70fx, 10, 0, 10, 0, laser_emitter);
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);   // 源 Boss 入口位置 (0,128)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
